validator:
function validate(input) {
  const [{ Project = [], Employees = [] }] = input;
  const staff = new Set(), pairs = new Set();
  for (const [id, name, team] of Employees) {
    if (id === null || name === null || team === null) return 'employee_id, name and team are required.';
    if (staff.has(id)) return `employee_id ${id} appears twice in Employees.`;
    staff.add(id);
  }
  for (const [project, employee, workload] of Project) {
    if (project === null || employee === null || workload === null) return 'project_id, employee_id and workload are required.';
    if (!staff.has(employee)) return `Project names employee ${employee}, who is not in Employees.`;
    if (workload <= 0) return 'workload must be positive.';
    const key = `${project}|${employee}`;
    if (pairs.has(key)) return `Employee ${employee} is assigned to project ${project} twice.`;
    pairs.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const names = ['Khaled', 'Ali', 'John', 'Doe', 'Mona', 'Sara', 'Omar', 'Lina'];
  const small = size === 'small';
  const teams = small ? ['A', 'B', 'C'] : ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];
  const staffCount = small ? pick(7) : 400;
  const Employees = [];
  for (let id = 1; id <= staffCount; id++) Employees.push([id, names[pick(names.length)], teams[pick(teams.length)]]);
  const Project = [];
  if (staffCount > 0) {
    // Few distinct workloads in small cases, so assignments often land exactly on the team average.
    const loads = [10, 20, 30, 45, 60, 90];
    const target = small ? pick(9) : 1500, projects = small ? 4 : 300;
    const pairs = new Set();
    for (let tries = 0; Project.length < target && tries < target * 5; tries++) {
      const project = 1 + pick(projects), employee = 1 + pick(staffCount);
      const key = `${project}|${employee}`;
      if (pairs.has(key)) continue;
      pairs.add(key);
      Project.push([project, employee, small ? loads[pick(loads.length)] : 1 + pick(100)]);
    }
  }
  return [{ Project, Employees }];
}
